@startuml

class Customer {
  + VATNumber
  + Name
  + PhoneNumber
  + Address
}

class Package {
  + IdentifierCode
  + Weight
  + Urgency
}

class DeliveryCenter {
  + Name
  + Address
}

class Courier {
  + VATNumber
  + Name
  + PhoneNumber
}

Customer "1" -- "1" DeliveryCenter : is associated to
Customer "1" -- "*" Package : sends
Customer "0..1" -- "*" Package : receives
Package "*" -- "1" DeliveryCenter : is routed through
Package "*" -- "1" DeliveryCenter : is delivered from
Package "0..1" -- "1" Courier : is assigned to
Courier "*" -- "1" DeliveryCenter : works for

@enduml

